        </div>
      `;
    } else {
      essentialHTML = '<div class="ph-med-essential"></div>';
    }

    return `
      <div class="ph-med-card">
        <div>
          <div class="ph-med-badges-row">
            <div class="ph-tag-group">
              <span class="ph-badge-tag ${badgeClass}">${badgeText}</span>
