          </div>
        `;
      } else {
        btnHTML = `<button class="ph-add-btn" onclick="addToCart('${it.item_code}')">+ Add</button>`;
      }

      return `
        <tr>
          <td>
            <div class="ph-tbl-med-title">${it.item_name}</div>
            <div class="ph-tbl-med-salt">${it.generic_name ? it.generic_name + ' &bull; ' : ''}${it.strength || ''}</div>
